class Solution {
    public long minCost(int[] nums, int[] costs) {
        int n = nums.length;
        int[] nextGE = new int[n], nextLess = new int[n];
        int[] st = new int[n];
        int sp = 0;
        for (int i = n - 1; i >= 0; i--) {
            while (sp > 0 && nums[st[sp - 1]] < nums[i]) sp--;
            nextGE[i] = sp > 0 ? st[sp - 1] : -1;
            st[sp++] = i;
        }
        sp = 0;
        for (int i = n - 1; i >= 0; i--) {
            while (sp > 0 && nums[st[sp - 1]] >= nums[i]) sp--;
            nextLess[i] = sp > 0 ? st[sp - 1] : -1;
            st[sp++] = i;
        }
        long[] dp = new long[n];
        Arrays.fill(dp, Long.MAX_VALUE);
        dp[0] = 0;
        for (int i = 0; i < n; i++) {
            if (dp[i] == Long.MAX_VALUE) continue;
            for (int j : new int[]{nextGE[i], nextLess[i]})
                if (j >= 0) dp[j] = Math.min(dp[j], dp[i] + costs[j]);
        }
        return dp[n - 1];
    }
}
